// PayProvider: HTTP con idempotencia y tolerancia a 503 y duplicados
function procesarPago(pedido) {
  const maxIntentos  = 3;                 // 1 intento primario + 3 reintentos
  const baseBackoff  = 500;               // ms
  const capBackoff   = 8000;              // ms (techo para evitar storming)
  const maxJitter    = 0.5;              // fracción de jitter aditivo
  const key = generarClaveIdempotencia(pedido); // e.g. UUID v4 o hash(pedido.id + fecha)
  const seen = nuevoSetMemoriaClave();      // caché en memoria (TTL corto)
  let intentosReintentados = 0;

  for (let intentos = 1; intentos <= maxIntentos; intentos++) {
    if (seen.has(key)) return { ok: true, resultado: seen.get(key), fuente: "cache" };

    const backoff = min(capBackoff, baseBackoff * Math.pow(2, intentos - 1));
    const jitter  = Math.random() * baseBackoff * maxJitter;
    await dormir(backoff + jitter);

    const resp = await invokeConTimeout(payProvider.charge(key), timeout = 3000);

    switch (resp.código) {
      case 200:
        seen.set(key, resp); return { ok: true, resultado: resp, fuente: "gateway" };

      case 503:   // infra saturada → reintentar con backoff
        intentosReintentados++;
        continue;

      case 429:   // rate limit → reintentar, pero a mayor backoff
        intentosReintentados++;
        continue;

      case 400: case 404: case 409: case 422:
      case 402: case 400_with_error("duplicated_payment"):
        // error determinista del gateway → NO reintentar (pago ya consumido o inválido)
        return { ok: false, error: resp.código, debeReintentar: false, fuente: "gateway" };

      case 408: case 500: case 502: case 504:
        // timeout del gateway o error upstream → reintentar (el request puede no haberse procesado)
        intentosReintentados++;
        continue;

      default:
        return { ok: false, error: resp.código, fuente: "gateway" };
    }
  }

  // Se agotaron los reintentos
  return {
    ok: false,
    error: "agotado_reintentos",
    clave: key,                 // crucial: el gateway pudo haberlo procesado
    fuente: "gateway",
    recuperacion: await consultarEstadoPago(key, timeout = 3000),
  };
}
```

**VEREDICTO: APOYO** (con reservas)

1. La clave de idempotencia + caché con TTL en memoria evita el doble cobro en el escenario de duplicado; pero `Set` en RAM se pierde en caída de node → se debe consultar el estado del gateway vía `consultarEstadoPago(key)` antes de declararlo fallido (lo marca el `default` final).
2. El backoff exponencial con `capBackoff` (8s) limita el *request storming* a una ventana de 3 intentos: el costo total de espera es ≈ 1.5s + 1s + 2s ≈ 4.5s por operación, aceptable; sin techo, el 8vo intento haría 128s.
3. La lógica "500/502/504 = reintentar" asume que el gateway NO procesó el charge. Sin trazabilidad de request-id, es una apuesta: falla el 10-15% de las veces en gateways sin idempotencia real del lado del banco.

**LA CONDICIÓN:** tu veredicto se torna RECHAZO si el proveedor (Stripe/Braintree/adyen) no confirma la recepción mediante idempotency-key en la propia request —es decir, si el duplicado llega dos veces y ambos se procesan. Si es así, la responsabilidad de deduplicación cae 100% en mi caché, no en la infra del proveedor.
